using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Runtime.InteropServices;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Threading;
class CorrectionCheck {
 static TV tv;static int count;static object Call(string n,params object[] a){return typeof(TV).GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(tv,a);}static object Field(string n){return typeof(TV).GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(tv);}static void Set(string n,object v){typeof(TV).GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(tv,v);}static List<Package> Apps(){return (List<Package>)Field("packages");}static IEnumerable<Package> Visible(){return ((DataGrid)Field("grid")).Items.Cast<Package>();}
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);Console.WriteLine("PASS "+text);count++;}static void Pump(Task task){while(!task.IsCompleted){var frame=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Background,new Action(()=>frame.Continue=false));Dispatcher.PushFrame(frame);Thread.Sleep(3);}task.GetAwaiter().GetResult();}
 static IEnumerable<T> Walk<T>(DependencyObject root)where T:DependencyObject{if(root is T)yield return (T)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var c in Walk<T>(VisualTreeHelper.GetChild(root,i)))yield return c;}
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr FindWindow(string cls,string title);[DllImport("user32.dll")]static extern bool PostMessage(IntPtr w,uint m,IntPtr p,IntPtr l);
 static void Undo(){var answer=Task.Run(()=>{for(int i=0;i<500;i++){var w=FindWindow("#32770","确认操作");if(w!=IntPtr.Zero){PostMessage(w,0x111,new IntPtr(6),IntPtr.Zero);return;}Thread.Sleep(10);}throw new Exception("undo confirmation did not appear");});Call("UndoRecent");Pump(answer);for(int i=0;i<2000&&(bool)Field("busy");i++)Pump(Task.Delay(5));Check(!(bool)Field("busy"),"undo finishes");}
 static void Warning(string page){Call("Show",page);tv.UpdateLayout();var texts=Walk<TextBlock>(tv).Where(t=>t.Text=="此操作不代表可完整恢复，甚至毫无作用。").ToList();Check(texts.Count==1,page+" has one exact recovery warning");Check(((SolidColorBrush)texts[0].Foreground).Color==((SolidColorBrush)new BrushConverter().ConvertFrom("#BE3349")).Color,page+" warning is red");}
 [STAThread]static int Main(string[] args){try{new Application();SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());tv=new TV();Set("serial","192.0.2.1:5555");Pump((Task)Call("Scan"));tv.Show();tv.UpdateLayout();string phase=args.Length==0?"active":args[0];
 if(phase=="category"){Call("Show","步骤3");var filter=(ComboBox)Field("groupFilter");Check(!filter.Items.Cast<string>().Contains("桌面精简"),"debloat dropdown excludes desktop");Check(filter.Items.Cast<string>().SequenceEqual(new[]{"全部应用","普通精简","深度精简","推荐卸载","谨慎卸载","疑似系统组件"}),"remaining dropdown choices preserved");Check(Apps().First(p=>p.Id=="com.vendor.tvhome").Group=="桌面精简","desktop classification preserved");Call("Show","步骤4");Check(Visible().Any(p=>p.Id=="com.vendor.tvhome"),"dedicated desktop page preserved");}
 if(phase=="restore"){Call("Show","重新再来");tv.UpdateLayout();Check(Walk<TextBlock>(tv).Any(t=>t.Text.Contains("可以尝试重新启动"))&&!Walk<TextBlock>(tv).Any(t=>t.Text.Contains("通常可以重新启用")),"recovery copy uses requested tentative wording");Warning("重新再来");Warning("恢复列表");Call("Show","步骤1");tv.UpdateLayout();Check(!Walk<TextBlock>(tv).Any(t=>t.Text=="此操作不代表可完整恢复，甚至毫无作用。"),"warning limited to recovery sections");}
 if(phase=="active"){
 Call("BeginUndoBatch",new List<Package>{Apps().First(p=>p.Id=="com.demo.video")},"uninstall");var task=(Task<string>)Call("ApplyChange","uninstall","com.demo.video");Pump(task);Call("RecordChange","uninstall","com.demo.video",task.Result);string undo=(string)Field("latestUndoFile");Pump((Task)Call("Scan"));Check(Apps().Any(p=>p.Id=="com.demo.video"&&p.State=="已卸载"),"master scan retains uninstalled package");foreach(string page in new[]{"步骤1","步骤3","步骤4","应用管理","AI 分析"}){Call("Show",page);Check(!Visible().Any(p=>p.State=="已卸载"||p.State=="需 APK 备份"),page+" excludes removed rows");}Call("Show","恢复列表");Check(Visible().Any(p=>p.Id=="com.demo.video"),"recovery retains uninstalled row");Check(File.Exists(undo)&&File.ReadAllText(undo).Contains("Success"),"undo result retained");Undo();Call("Show","步骤3");Check(Visible().Any(p=>p.Id=="com.demo.video"&&p.State=="已安装"),"actual undo restores debloat row");Call("Show","步骤1");Check(Visible().Any(p=>p.Id=="com.demo.video"),"actual undo restores management row");Check(File.Exists(undo.Replace(".json",".done.json")),"undo batch completion recorded");
 File.WriteAllText("uninstall-fails.flag","");task=(Task<string>)Call("ApplyChange","uninstall","com.demo.video");Pump(task);Call("RecordChange","uninstall","com.demo.video",task.Result);Pump((Task)Call("Scan"));Call("Show","步骤3");Check(Visible().Any(p=>p.Id=="com.demo.video"&&p.State=="已停用"),"failed uninstall with disabled fallback stays visible");File.WriteAllText("disable-fails.flag","");Pump((Task)Call("RestorePackage","com.demo.video"));bool failed=false;try{Pump((Task)Call("ApplyChange","uninstall","com.demo.video"));}catch{failed=true;}Pump((Task)Call("Scan"));Call("Show","步骤1");Check(failed&&Visible().Any(p=>p.Id=="com.demo.video"&&p.State=="已安装"),"failed uninstall and failed fallback stay visible");
 Call("RecordChange","uninstall","com.demo.orphan","Success");File.AppendAllText(Path.Combine(Environment.GetEnvironmentVariable("TVSTUDIO_DATA"),"history.tsv"),"other-device\tuninstall\tcom.foreign.only\tdate\tSuccess\n");Call("LoadHistoryEntries");Call("Bind");Check(!Visible().Any(p=>p.Id=="com.demo.orphan"),"history-only removed row hidden from active view");Call("Show","恢复列表");Check(Visible().Any(p=>p.Id=="com.demo.orphan")&&!Apps().Any(p=>p.Id=="com.foreign.only"),"history recovery retained and device isolated");Set("serial","other-device");Set("packages",new List<Package>());Call("LoadHistoryEntries");Check(Apps().Any(p=>p.Id=="com.foreign.only")&&!Apps().Any(p=>p.Id=="com.demo.orphan"),"switch device isolates recovery history");}
 tv.Close();Console.WriteLine(count+" correction checks passed ("+phase+"); simulated ADB only");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
